// ═══ BUG: JVM never exits ═══
public static void main(String[] args) {
    ExecutorService pool = Executors.newFixedThreadPool(10);
    pool.submit(() -> System.out.println("Trade settled"));
    System.out.println("main() finished!");
    // main() returns, but JVM does NOT exit!
    // 10 pool threads are non-daemon, alive, waiting for tasks.
    // JVM: "still have non-daemon threads → stay alive!"
    // Process hangs FOREVER. Must kill -9!
}

// ═══ FIX: shutdown the pool ═══
public static void main(String[] args) {
    ExecutorService pool = Executors.newFixedThreadPool(10);
    try {
        pool.submit(() -> System.out.println("Trade settled"));
    } finally {
        pool.shutdown();  // stop accepting, finish running tasks
        pool.awaitTermination(30, TimeUnit.SECONDS);  // wait up to 30s
        if (!pool.isTerminated()) {
            pool.shutdownNow();  // force stop
        }
    }
    // All 10 workers finished → JVM exits cleanly!
}

// ═══ SHUTDOWN HOOK — emergency cleanup ═══
Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    System.out.println("Shutdown hook: cleaning up...");
    pool.shutdownNow();
    try { pool.awaitTermination(10, TimeUnit.SECONDS); } catch (InterruptedException e) { }
}));
// Runs on: System.exit(), SIGTERM (kill), SIGINT (Ctrl+C)
// Does NOT run on: SIGKILL (kill -9), JVM crash

// ═══ COMMON NON-DAEMON THREADS THAT PREVENT EXIT ═══
// 1. ExecutorService threads (Executors.newFixedThreadPool)
// 2. ScheduledExecutorService threads
// 3. java.util.Timer thread
// 4. AWT/Swing Event Dispatch Thread
// 5. RMI/JMX threads
// 6. Any Thread created without setDaemon(true)

// ═══ FIX: daemon thread factory ═══
ExecutorService daemonPool = Executors.newFixedThreadPool(10, r -> {
    Thread t = new Thread(r);
    t.setDaemon(true);  // won't prevent JVM exit!
    return t;
});
// BUT: tasks may be killed mid-execution on JVM exit!
// Use only for optional background tasks, not critical work.

// ═══ CLEAN SHUTDOWN PATTERN (production) ═══
ExecutorService pool = Executors.newFixedThreadPool(10);
Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    pool.shutdown();
    try {
        if (!pool.awaitTermination(30, TimeUnit.SECONDS)) {
            pool.shutdownNow();
            pool.awaitTermination(10, TimeUnit.SECONDS);
        }
    } catch (InterruptedException e) {
        pool.shutdownNow();
        Thread.currentThread().interrupt();
    }
}));
