package com.bank.jvmexit;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class JvmExitTest {

    // ═══ Non-daemon pool threads stay alive ═══
    @Test
    void poolThreads_areNonDaemon() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        AtomicBoolean isDaemon = new AtomicBoolean(true);
        CountDownLatch done = new CountDownLatch(1);

        pool.submit(() -> {
            isDaemon.set(Thread.currentThread().isDaemon());
            done.countDown();
        });
        done.await();

        assertThat(isDaemon.get()).isFalse();  // NON-daemon! Prevents JVM exit!
        pool.shutdown();
    }

    // ═══ shutdown() stops the pool ═══
    @Test
    void shutdown_stopsPool() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        pool.submit(() -> { /* quick task */ });

        pool.shutdown();  // no new tasks accepted
        boolean terminated = pool.awaitTermination(5, TimeUnit.SECONDS);
        assertThat(terminated).isTrue();
        assertThat(pool.isTerminated()).isTrue();
    }

    // ═══ shutdownNow() interrupts running tasks ═══
    @Test
    void shutdownNow_interruptsRunning() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        AtomicBoolean interrupted = new AtomicBoolean(false);

        pool.submit(() -> {
            try { Thread.sleep(10000); }
            catch (InterruptedException e) { interrupted.set(true); }
        });

        Thread.sleep(100);
        pool.shutdownNow();  // interrupts!
        pool.awaitTermination(5, TimeUnit.SECONDS);

        assertThat(interrupted.get()).isTrue();  // task was interrupted!
    }

    // ═══ Daemon pool: doesn't prevent JVM exit ═══
    @Test
    void daemonPool_doesNotPreventExit() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2, r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });
        AtomicBoolean isDaemon = new AtomicBoolean(false);
        CountDownLatch done = new CountDownLatch(1);

        pool.submit(() -> {
            isDaemon.set(Thread.currentThread().isDaemon());
            done.countDown();
        });
        done.await();

        assertThat(isDaemon.get()).isTrue();  // daemon! Won't prevent exit!
        pool.shutdown();
    }

    // ═══ Clean shutdown pattern ═══
    @Test
    void cleanShutdownPattern() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int i = 0; i < 10; i++) {
            pool.submit(() -> {
                try { Thread.sleep(50); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        // Clean shutdown:
        pool.shutdown();                     // step 1: stop accepting
        if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {  // step 2: wait
            pool.shutdownNow();              // step 3: force if timeout
            pool.awaitTermination(5, TimeUnit.SECONDS);  // step 4: wait again
        }
        assertThat(pool.isTerminated()).isTrue();  // all done!
    }
}
